from pathlib import Path

root = Path(__file__).resolve().parents[1]
frontend = root / 'frontend'

# Post-process implementation generated by ux11_apply.py.
dash_path = frontend / 'lib/features/dashboard/dashboard_convergent_screen.dart'
dash = dash_path.read_text()
dash = dash.replace(
    "child: InkWell(\n            onTap: () => GoRouter.of(context).go('/importer'),",
    "child: InkWell(\n            key: const ValueKey('dashboard-import-action'),\n            onTap: () => GoRouter.of(context).go('/importer'),",
    1,
)
dash_path.write_text(dash)

for relative in [
    'lib/features/medications/medication_screen.dart',
    'lib/features/reminders/reminders_screen.dart',
]:
    path = frontend / relative
    text = path.read_text()
    text = text.replace(
        'padding: const EdgeInsets.fromLTRB(20, 16, 20, 40),',
        'padding: const EdgeInsetsDirectional.fromSTEB(20, 16, 20, 40),',
    )
    text = text.replace(
        'if (date == null || !mounted) return;',
        'if (date == null || !context.mounted) return;',
    )
    text = text.replace(
        'if (time == null || !mounted) return;',
        'if (time == null || !context.mounted) return;',
    )
    path.write_text(text)

# UX-11 mobile nav contract: four destinations + central add.
(frontend / 'test/p0_ux_8_mobile_navigation_test.dart').write_text(r'''import 'package:amina/features/navigation/main_shell.dart';
import 'package:amina/l10n/app_localizations.dart';
import 'package:amina/services/api_client.dart';
import 'package:amina/services/modules_provider.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:go_router/go_router.dart';
import 'package:provider/provider.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  Future<GoRouter> pumpNavigation(
    WidgetTester tester, {
    required Locale locale,
  }) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;

    final api = ApiClient(baseUrl: 'http://127.0.0.1:1');
    final modules = ModulesProvider(api);
    final router = GoRouter(
      initialLocation: '/dashboard',
      routes: [
        GoRoute(
          path: '/ajouter',
          builder: (_, __) => const Scaffold(body: Text('route:/ajouter')),
        ),
        ShellRoute(
          builder: (_, __, child) => MainShell(child: child),
          routes: [
            for (final route in const [
              '/dashboard',
              '/summary',
              '/journal',
              '/importer',
              '/profile',
            ])
              GoRoute(
                path: route,
                builder: (_, __) =>
                    Scaffold(body: Center(child: Text('route:$route'))),
              ),
          ],
        ),
      ],
    );

    await tester.pumpWidget(
      ChangeNotifierProvider<ModulesProvider>.value(
        value: modules,
        child: MaterialApp.router(
          routerConfig: router,
          locale: locale,
          localizationsDelegates: AppLocalizations.localizationsDelegates,
          supportedLocales: AppLocalizations.supportedLocales,
        ),
      ),
    );
    await tester.pumpAndSettle();
    return router;
  }

  Finder destination(String route) => find.byKey(ValueKey('mobile-nav-$route'));
  Finder get addDestination => find.byKey(const ValueKey('mobile-nav-add'));

  void expectApprovedDestinations() {
    for (final route in const [
      '/dashboard',
      '/journal',
      '/summary',
      '/profile',
    ]) {
      expect(destination(route), findsOneWidget);
    }
    expect(destination('/importer'), findsNothing);
    expect(addDestination, findsOneWidget);
  }

  void expectTouchTargets(WidgetTester tester) {
    for (final route in const [
      '/dashboard',
      '/journal',
      '/summary',
      '/profile',
    ]) {
      final size = tester.getSize(destination(route));
      expect(size.width, greaterThanOrEqualTo(48));
      expect(size.height, greaterThanOrEqualTo(48));
    }
    final addSize = tester.getSize(addDestination);
    expect(addSize.width, greaterThanOrEqualTo(48));
    expect(addSize.height, greaterThanOrEqualTo(48));
  }

  Finder semanticsContaining(String label) =>
      find.bySemanticsLabel(RegExp(RegExp.escape(label)));

  testWidgets('390px French navigation matches approved UX-11 semantics', (
    tester,
  ) async {
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final semantics = tester.ensureSemantics();
    final router = await pumpNavigation(tester, locale: const Locale('fr'));
    addTearDown(router.dispose);

    expectApprovedDestinations();
    expect(
      Directionality.of(tester.element(destination('/dashboard'))),
      TextDirection.ltr,
    );
    for (final label in const ['Accueil', 'Mesures', 'Rapports', 'Profil']) {
      expect(find.text(label), findsOneWidget);
      expect(semanticsContaining(label), findsWidgets);
    }
    expectTouchTargets(tester);

    await tester.tap(destination('/journal'));
    await tester.pumpAndSettle();
    expect(router.routeInformationProvider.value.uri.path, '/journal');
    expectApprovedDestinations();

    await tester.tap(addDestination);
    await tester.pumpAndSettle();
    expect(router.routeInformationProvider.value.uri.path, '/ajouter');
    expect(tester.takeException(), isNull);
    semantics.dispose();
  });

  testWidgets('390px Arabic navigation is RTL and route-aware', (tester) async {
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final semantics = tester.ensureSemantics();
    final router = await pumpNavigation(tester, locale: const Locale('ar'));
    addTearDown(router.dispose);

    expectApprovedDestinations();
    expect(
      Directionality.of(tester.element(destination('/dashboard'))),
      TextDirection.rtl,
    );
    for (final label in const ['الرئيسية', 'القياسات', 'التقارير', 'الملف الشخصي']) {
      expect(find.text(label), findsOneWidget);
      expect(semanticsContaining(label), findsWidgets);
    }
    expectTouchTargets(tester);

    await tester.tap(destination('/summary'));
    await tester.pumpAndSettle();
    expect(router.routeInformationProvider.value.uri.path, '/summary');
    expectApprovedDestinations();
    expect(tester.takeException(), isNull);
    semantics.dispose();
  });
}
''')

# Navigation remains real while Import is deliberately reached outside bottom nav.
real_actions = frontend / 'test/p0_real_actions_contract_test.dart'
text = real_actions.read_text()
old = r'''  test('mobile navigation derives every destination including Importer', () {
    final module = _read('lib/modules/diabetes_module.dart');
    final shell = _read('lib/features/navigation/main_shell.dart');

    expect(module, contains("route: '/importer'"));
    expect(
      shell,
      contains('for (var index = 0; index < entries.length; index++)'),
    );
    expect(shell, contains('_GlassNavDestination('));
    expect(shell, contains('entry: entries[index]'));
    expect(shell, contains("ValueKey('mobile-nav-\${entry.route}')"));
    expect(shell, contains('GoRouter.of(context).go(entries[index].route)'));
  });'''
new = r'''  test('mobile navigation exposes approved destinations while Import stays reachable', () {
    final module = _read('lib/modules/diabetes_module.dart');
    final shell = _read('lib/features/navigation/main_shell.dart');
    final dashboard = _read('lib/features/dashboard/dashboard_convergent_screen.dart');

    expect(module, contains("route: '/importer'"));
    expect(shell, contains("entry.route != '/importer'"));
    expect(shell, contains('_GlassNavDestination('));
    expect(shell, contains('entry: mobileEntries[index]'));
    expect(shell, contains("ValueKey('mobile-nav-\${entry.route}')"));
    expect(shell, contains('GoRouter.of(context).go(mobileEntries[index].route)'));
    expect(shell, contains("GoRouter.of(context).go('/ajouter')"));
    expect(dashboard, contains("ValueKey('dashboard-import-action')"));
    expect(dashboard, contains("GoRouter.of(context).go('/importer')"));
  });'''
assert old in text
real_actions.write_text(text.replace(old, new, 1))

