# Latest Drift schema is v10. Also certify that the new v10 tables exist after legacy upgrades.
for rel in [
    'test/data/drift/glycemic_context_migration_test.dart',
    'test/data/drift/meal_items_migration_test.dart',
    'test/data/drift/meal_portions_migration_test.dart',
    'test/data/drift/ramadan_period_migration_test.dart',
]:
    path = frontend / rel
    text = path.read_text().replace("expect(version.data['user_version'], 9);", "expect(version.data['user_version'], 10);")
    probe = """        final v10Tables = await db.customSelect(\n          \"SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('medication_events', 'reminders')\",\n        ).get();\n        expect(v10Tables.map((row) => row.data['name']).toSet(), {'medication_events', 'reminders'});\n"""
    anchor = "        expect(version.data['user_version'], 10);"
    if anchor in text and 'final v10Tables' not in text:
        text = text.replace(anchor, anchor + '\n' + probe, 1)
    path.write_text(text)
